api_client_code = '''package com.itmeansbigmountain.rivalradar;

import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.HashMap;
import java.util.Map;

public class WOMApiHelper {

    private static final String WOM_API_BASE = "https://api.wiseoldman.net/v1";
    private static final HttpClient client = HttpClient.newBuilder()
        .connectTimeout(Duration.ofSeconds(10))
        .build();

    public static String getPlayersBySkill(String skill, int limit) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(java.net.URI.create(WOM_API_BASE + "/hiscores/" + skill + "?limit=" + limit))
            .header("User-Agent", "OSRS-Plugin")
            .timeout(Duration.ofSeconds(15))
            .GET()
            .build();

        HttpResponse<String> response = client.send(request, 
            HttpResponse.BodyHandlers.ofString());

        return response.body();
    }

    public static String getPlayerData(String username) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(java.net.URI.create(WOM_API_BASE + "/player/" + username))
            .header("User-Agent", "OSRS-Plugin")
            .timeout(Duration.ofSeconds(15))
            .GET()
            .build();

        HttpResponse<String> response = client.send(request, 
            HttpResponse.BodyHandlers.ofString());

        return response.body();
    }

    public static String formatXPComparison(String player1, String player2, String skill) {
        Map<String, Object> result = new HashMap<>();
        result.put("player1", player1);
        result.put("player2", player2);
        result.put("skill", skill);
        result.put("comparison", "xp_comparison_pending");
        return "Comparison feature requires WOM API authentication. Check config for WOM_KEY setting.";
    }
}
'''

with open(src_dir / 'WOMApiHelper.java', 'w') as f:
    f.write(api_client_code)

print(f"Created WOMApiHelper.java in {src_dir}")"}

